"""Every catalog example, generated by `kit_docs.py examples`, builds, passes the checks and verifies.

Builds and static checks always run. The browser verify tests need `scripts/verify/node_modules`,
node and a launchable browser, and skip otherwise; nothing here touches the network.
"""

from __future__ import annotations

import json
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
SKILL = ROOT / "skills" / "writing-html-artifacts"
CLI = SKILL / "scripts" / "quirk_html.py"
KIT_DOCS = SKILL / "scripts" / "kit_docs.py"
CATALOG = SKILL / "vendor" / "kit" / "1.0.0" / "catalog.json"

NOTE_TAG = "q-diff-note"
CATALOG_TAGS = [e["tag"] for e in json.loads(CATALOG.read_text(encoding="utf-8"))["elements"]]
EXAMPLE_TAGS = [tag for tag in CATALOG_TAGS if tag != NOTE_TAG]


def _cli(*args: object) -> subprocess.CompletedProcess[str]:
    return subprocess.run([sys.executable, str(CLI), *map(str, args)], capture_output=True, text=True, check=False)


@pytest.fixture(scope="module")
def example_sources(tmp_path_factory: pytest.TempPathFactory) -> Path:
    out = tmp_path_factory.mktemp("kit-examples")
    proc = subprocess.run([sys.executable, str(KIT_DOCS), "examples", str(out)], capture_output=True, text=True, check=False)
    assert proc.returncode == 0, proc.stdout + proc.stderr
    written = json.loads(proc.stdout)["written"]
    assert sorted(Path(p).name for p in written) == sorted(f"{tag}.src.html" for tag in EXAMPLE_TAGS)
    return out


@pytest.fixture(scope="module")
def built_examples(example_sources: Path) -> dict[str, tuple[Path, dict]]:
    """Each example's built page and the build's JSON result, keyed by tag."""
    pages: dict[str, tuple[Path, dict]] = {}
    for tag in EXAMPLE_TAGS:
        page = example_sources / f"{tag}.html"
        proc = _cli("build", example_sources / f"{tag}.src.html", "--out", page)
        assert proc.returncode == 0, f"{tag}: {proc.stdout}{proc.stderr}"
        pages[tag] = (page, json.loads(proc.stdout))
    return pages


def test_one_example_per_element_except_the_note(example_sources: Path) -> None:
    assert NOTE_TAG in CATALOG_TAGS
    assert sorted(p.name for p in example_sources.glob("*.src.html")) == sorted(f"{tag}.src.html" for tag in EXAMPLE_TAGS)


@pytest.mark.parametrize("tag", EXAMPLE_TAGS)
def test_example_builds_with_every_check_passing(built_examples: dict, tag: str) -> None:
    page, result = built_examples[tag]
    assert result["checks"]["passed"] is True, result["checks"]
    assert result["checks"]["failures"] == []
    check = _cli("check", page)
    assert check.returncode == 0, check.stdout + check.stderr
    assert json.loads(check.stdout)["passed"] is True


@pytest.mark.parametrize("tag", EXAMPLE_TAGS)
def test_example_carries_the_kit_and_only_q_chart_adds_chartjs(built_examples: dict, tag: str) -> None:
    page, result = built_examples[tag]
    html = page.read_text(encoding="utf-8")
    assert html.count('<script data-quirk-lib="kit@1.0.0">') == 1
    assert html.count('<style data-quirk-lib="kit@1.0.0">') == 1
    assert result["libraries"]["kit"] == "1.0.0"
    assert ('<script data-quirk-lib="chartjs@' in html) is (tag == "q-chart")
    assert f"<{tag}" in html


@pytest.fixture(scope="module")
def browser_ready(built_examples: dict) -> None:
    if not (SKILL / "scripts" / "verify" / "node_modules").is_dir():
        pytest.skip("scripts/verify/node_modules is absent; run pnpm install there")
    if shutil.which("node") is None:
        pytest.skip("node is not installed")
    page = built_examples[EXAMPLE_TAGS[0]][0]
    proc = _cli("verify", page, "--out-dir", page.with_suffix(".probe"))
    if json.loads(proc.stdout)["status"] == "not-browser-verified":
        pytest.skip("no browser could be launched")


@pytest.mark.usefixtures("browser_ready")
@pytest.mark.parametrize("no_js", [False, True], ids=["js", "no-js"])
@pytest.mark.parametrize("tag", EXAMPLE_TAGS)
def test_example_passes_verify(built_examples: dict, tag: str, no_js: bool) -> None:
    page = built_examples[tag][0]
    proc = _cli("verify", page, *(["--no-js"] if no_js else []))
    result = json.loads(proc.stdout)
    assert result["status"] == "passed", result
    assert proc.returncode == 0, proc.stdout + proc.stderr
    assert result["no_js"] is no_js
    assert all(check["passed"] for check in result["checks"].values()), result["checks"]
    assert ("fallback" in result["checks"]) is no_js
